// A Verus program that finds the maximum element of a non‐empty slice of integers.
// The result m satisfies:
//   1) ∀i < a.len(): m ≥ a[i]
//   2) ∃i < a.len(): m == a[i]

verus! {
    // maxArray takes a non‐empty slice `a` and returns its maximum element `m`.
    pub fn maxArray(a: &[int]) -> (m: int)
        requires
            a.len() > 0,
        ensures
            // m is an upper bound for all elements
            forall |i: usize| i < a.len() ==> m >= a[i],
        ensures
            // m is actually attained at some index
            exists |i: usize| i < a.len() && m == a[i],
    {
        // Initialize m0 to the first element, and start scanning from i = 1.
        let mut m0: int = a[0];
        let mut i: usize = 1;

        // Loop invariant 1: i never exceeds a.len()
        // Loop invariant 2: m0 is ≥ every element in a[0..i)
        // Loop invariant 3: There is some j < i with m0 == a[j]
        // Decreases clause ensures termination.
        while i < a.len()
            invariant i <= a.len()
            invariant forall |j: usize| j < i ==> m0 >= a[j]
            invariant exists |j: usize| j < i && m0 == a[j]
            decreases a.len() - i
        {
            let ai = a[i];
            if ai > m0 {
                m0 = ai;
            }
            i = i + 1;
        }

        // After the loop, i == a.len(), invariants give the desired post‐conditions.
        m0
    }
}